import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as space from "./space.ts";

// Vectors are generated by ts/tools/gen-render-vectors from Go's real render package (build tag javascript).
interface Pair {
  in: string;
  out: string | null;
}
interface Vectors {
  space0: Pair[];
  allowSpace: [number, number, number][];
  runeKinds: [number, number, number][];
  addSpaceAtBoundary: [string, number, string][];
}
const data: Vectors = JSON.parse(readFileSync(new URL("./testdata/render_vectors.json", import.meta.url), "utf8"));

test("Space0 matches Go", () => {
  assert.ok(data.space0.length >= 400, "at least 400 vectors");
  for (const v of data.space0) {
    assert.equal(space.Space0(v.in), v.out, "input " + JSON.stringify(v.in));
  }
});

test("allowSpace matches Go on every pair of the rune pool", () => {
  for (const [a, b, out] of data.allowSpace) {
    assert.equal(space.allowSpace(a, b) ? 1 : 0, out, "pair U+" + a.toString(16) + " U+" + b.toString(16));
  }
});

test("isCJK and isFullWidth match Go", () => {
  for (const [r, cjk, fw] of data.runeKinds) {
    assert.equal(space.isCJK(r) ? 1 : 0, cjk, "isCJK U+" + r.toString(16));
    assert.equal(space.isFullWidth(r) ? 1 : 0, fw, "isFullWidth U+" + r.toString(16));
  }
});

test("addSpaceAtBoundary matches Go", () => {
  for (const [prefix, r, out] of data.addSpaceAtBoundary) {
    assert.equal(space.addSpaceAtBoundary(prefix, r), out, "prefix " + JSON.stringify(prefix) + " rune U+" + r.toString(16));
  }
});
